contract InvMutTest is Test {
    MyContract c;
    function setUp() public { c = new MyContract(); }
    function testFuzz_property(uint256 amount, address receiver) public {
        vm.assume(amount > 0);
        vm.assume(receiver != address(0));
        vm.assume(receiver != address(c));
        vm.deal(address(c), amount);
        uint256 beforeBal = receiver.balance;
        bool ok;
        try c.sendTo(receiver, amount) {
            ok = true;
        } catch {
            ok = false;
        }
        if (ok) {
            assertTrue(receiver.balance == beforeBal + amount);
        }
    }
